198	// Counts current tag usage across the live documents. Deleted documents are
199	// absent from the workspace and therefore never counted; history is ignored.
200	function tagStats(workspace) {
201	  const counts = new Map();
202	  for (const document of workspace.list()) {
203	    for (const tag of document.tags) counts.set(tag, (counts.get(tag) ?? 0) + 1);
204	  }
205	  return [...counts.entries()]
206	    .map(([tag, count]) => ({ tag, count }))
207	    .sort((a, b) => compareCodePoints(a.tag, b.tag));
208	}
209	
210	// Validates the rewrite envelope and every rule, returning normalized
211	// `{ rules, dryRun }` as `[{ from, to }]` pairs of trimmed, lowercased names
212	// (`to` stays `null` for removals). Structural problems, empty normalized
213	// names, duplicate sources, and out-of-range rule counts are INVALID_TAG_RULES.
214	function validateTagRules(data) {
215	  if (!data || typeof data !== 'object' || Array.isArray(data)) {
216	    throw new HttpError(400, 'INVALID_TAG_RULES', 'rewrite body must be an object');
217	  }
218	  for (const key of Object.keys(data)) {
219	    if (key !== 'rules' && key !== 'dryRun') {
220	      throw new HttpError(400, 'INVALID_TAG_RULES', `unknown rewrite field: ${key}`);
221	    }
222	  }
223	  if (!Array.isArray(data.rules)) {
224	    throw new HttpError(400, 'INVALID_TAG_RULES', 'rules must be an array');
225	  }
226	  if (data.rules.length < 1 || data.rules.length > MAX_TAG_RULES) {
227	    throw new HttpError(400, 'INVALID_TAG_RULES', `rules must contain 1 to ${MAX_TAG_RULES} items`);
228	  }
229	  const dryRun = data.dryRun === undefined ? false : data.dryRun;
230	  if (typeof dryRun !== 'boolean') {
231	    throw new HttpError(400, 'INVALID_TAG_RULES', 'dryRun must be a boolean');
232	  }
233	
234	  const rules = data.rules.map((rule, index) => {
235	    if (!rule || typeof rule !== 'object' || Array.isArray(rule)) {
236	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}] must be an object`);
237	    }
238	    const keys = Object.keys(rule);
239	    if (keys.length !== TAG_RULE_FIELDS.length || !TAG_RULE_FIELDS.every((key) => keys.includes(key))) {
240	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}] must contain exactly from and to`);
241	    }
242	    if (typeof rule.from !== 'string') {
243	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}].from must be a string`);
244	    }
245	    if (typeof rule.to !== 'string' && rule.to !== null) {
246	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}].to must be a string or null`);
247	    }
248	    const from = rule.from.trim().toLowerCase();
249	    const to = rule.to === null ? null : rule.to.trim().toLowerCase();
250	    if (!from) {
251	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}].from must not be blank`);
252	    }
253	    if (to !== null && !to) {
254	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}].to must not be blank`);
255	    }
256	    return { from, to };
257	  });
258	
259	  const seen = new Set();
260	  for (const { from } of rules) {
261	    if (seen.has(from)) {
262	      throw new HttpError(400, 'INVALID_TAG_RULES', `duplicate source tag after normalization: ${from}`);
263	    }
264	    seen.add(from);
265	  }
266	
267	  return { rules, dryRun };
268	}
269	
270	// Validates the reconcile envelope `{ base, incoming, dryRun? }`, where base
271	// and incoming are version-1 snapshot objects (strings are not accepted at
272	// this layer; malformed JSON is rejected earlier by the shared body parser).
273	// Snapshot contents themselves are validated by normalizeSnapshot via the
274	// reconcile core, which reports INVALID_SNAPSHOT.
275	function validateReconcileRequest(data) {
276	  if (!data || typeof data !== 'object' || Array.isArray(data)) {
277	    throw new HttpError(400, 'INVALID_OPTIONS', 'reconcile body must be an object');
278	  }
279	  for (const key of Object.keys(data)) {
280	    if (key !== 'base' && key !== 'incoming' && key !== 'dryRun') {
281	      throw new HttpError(400, 'INVALID_OPTIONS', `unknown reconcile field: ${key}`);
282	    }
283	  }
284	  if (!data.base || typeof data.base !== 'object' || Array.isArray(data.base)) {
285	    throw new HttpError(400, 'INVALID_OPTIONS', 'base must be a snapshot object');
286	  }
287	  if (!data.incoming || typeof data.incoming !== 'object' || Array.isArray(data.incoming)) {
288	    throw new HttpError(400, 'INVALID_OPTIONS', 'incoming must be a snapshot object');
289	  }
290	  const dryRun = data.dryRun === undefined ? false : data.dryRun;
291	  if (typeof dryRun !== 'boolean') {
292	    throw new HttpError(400, 'INVALID_OPTIONS', 'dryRun must be a boolean');
293	  }
294	  return { base: data.base, incoming: data.incoming, dryRun };
295	}
296	
297	// A document server holds one Workspace and, when a history store is supplied,
298	// a per-document revision ledger. Every committed change is persisted through
299	// `save(snapshot, historySnapshot)` before the in-memory state is swapped, so a
300	// failed save leaves memory, queries, history, and the original files
301	// untouched. Everything here is synchronous, so a commit is atomic with
302	// respect to other requests.
303	export function createDocumentServer({ workspace, save, history = null }) {
304	  let current = workspace;
305	  let ledger = history;
306	
307	  const currentEtag = () => `"${current.exportJSON().checksum}"`;
308	
309	  function requireIfMatch(req) {
310	    const value = req.headers['if-match'];
311	    if (value === undefined) {
312	      throw new HttpError(428, 'PRECONDITION_REQUIRED', 'write requests require an If-Match header');
313	    }
314	    if (!ETAG_PATTERN.test(value)) {
315	      throw new HttpError(400, 'INVALID_IF_MATCH', 'If-Match must be a double-quoted checksum');
316	    }
317	    if (value !== currentEtag()) {
318	      throw new HttpError(412, 'PRECONDITION_FAILED', 'If-Match checksum is stale');
319	    }
320	  }
321	
322	  function assertTitleFree(candidate, title) {
323	    const trimmed = title.trim();
324	    for (const existing of candidate.list()) {
325	      if (existing.title === trimmed) {
326	        throw new HttpError(409, 'CONFLICT', `title already in use: ${trimmed}`);
327	      }
328	    }
329	  }
330	
331	  // The single commit rule shared by every write entry point (single-document
332	  // edits and restores, batches, tag rewrites, and snapshot reconciles).
333	  // `mutate` runs against a candidate workspace copied from the live state
334	  // plus a cloned ledger, applying its content changes and appending one
335	  // history record per actually-changed document. It returns a result value to
336	  // commit the projected state, or false to signal a content-preserving
337	  // request (normalized content unchanged): the request still succeeds with
338	  // the current snapshot and ETag, but no revision is consumed and nothing is
339	  // persisted. With `dryRun` the projected snapshot and result are returned
340	  // without persisting or swapping state. Otherwise the snapshot — and, when
341	  // history is enabled, the ledger bound to its checksum — is saved first, and
342	  // the in-memory state swaps in only after the save succeeds, so a failed
343	  // save leaves memory, queries, history, and the original files untouched.
344	  // Everything here is synchronous, so a commit is atomic with respect to
345	  // other requests.
346	  function commit(mutate, { dryRun = false } = {}) {
347	    const candidate = new Workspace();
348	    for (const document of current.list()) candidate.add(document);
349	    const nextLedger = ledger ? ledger.clone() : null;
350	    const result = mutate(candidate, nextLedger);
351	    if (result === false) {
352	      return { snapshot: current.exportJSON(), result: null };
353	    }
354	    const snapshot = candidate.exportJSON();
355	    if (!dryRun) {
356	      save(snapshot, nextLedger ? nextLedger.exportJSON(snapshot.checksum) : null);
357	      current = candidate;
358	      ledger = nextLedger;
359	    }
360	    return { snapshot, result };
361	  }
362	
363	  // Applies every operation in one atomic commit. Existence and
364	  // restore-version checks all run against the pre-commit state, so a batch is
365	  // rejected whole if any operation would fail. Title conflicts are checked
366	  // against the final projected set, making swaps and release-then-reuse
367	  // independent of operation order. Each actually-changed document appends one
368	  // record; a normalized-identical replace or restore appends nothing. Returns
369	  // `{ snapshot, changed }` without persisting when `dryRun` is true or the
370	  // batch is content-preserving.
371	  function commitBatch(operations, dryRun) {
372	    // Pre-commit state checks.
373	    for (const op of operations) {
374	      if (op.type === 'create') {
375	        if (current.get(op.document.id)) {
376	          throw new HttpError(409, 'CONFLICT', `document already exists: ${op.document.id}`);
377	        }
378	      } else if (op.type === 'replace') {
379	        if (!current.get(op.document.id)) {
380	          throw new HttpError(404, 'NOT_FOUND', `document not found: ${op.document.id}`);
381	        }
382	      } else if (op.type === 'delete') {
383	        if (!current.get(op.id)) {
384	          throw new HttpError(404, 'NOT_FOUND', `document not found: ${op.id}`);
385	        }
386	      } else if (op.type === 'restore') {
387	        if (!ledger) {
388	          throw new HttpError(404, 'NOT_FOUND', 'history is not enabled');
389	        }
390	        const chain = ledger.entries(op.id);
391	        if (!chain) {
392	          throw new HttpError(404, 'NOT_FOUND', `document never existed: ${op.id}`);
393	        }
394	        const target = ledger.entry(op.id, op.revision);
395	        if (!target) {
396	          throw new HttpError(404, 'NOT_FOUND', `unknown revision ${op.revision} for document ${op.id}`);
397	        }
398	        if (target.action === 'delete') {
399	          throw new HttpError(400, 'INVALID_REVISION', `revision ${op.revision} of document ${op.id} is a delete and cannot be restored`);
400	        }
401	      }
402	    }
403	
404	    const { snapshot, result } = commit((candidate, nextLedger) => {
405	      let changed = false;
406	      for (const op of operations) {
407	        if (op.type === 'create') {
408	          candidate.add(op.document);
409	          if (nextLedger) nextLedger.record(op.document.id, 'create', candidate.get(op.document.id));
410	          changed = true;
411	        } else if (op.type === 'replace') {
412	          const before = current.get(op.document.id);
413	          candidate.remove(op.document.id);
414	          candidate.add(op.document);
415	          const stored = candidate.get(op.document.id);
416	          if (!sameDocument(before, stored)) {
417	            if (nextLedger) nextLedger.record(op.document.id, 'replace', stored);
418	            changed = true;
419	          }
420	        } else if (op.type === 'delete') {
421	          candidate.remove(op.id);
422	          if (nextLedger) nextLedger.record(op.id, 'delete', null);
423	          changed = true;
424	        } else if (op.type === 'restore') {
425	          const before = current.get(op.id);
426	          const target = ledger.entry(op.id, op.revision);
427	          candidate.remove(op.id);
428	          candidate.add(target.document);
429	          const stored = candidate.get(op.id);
430	          if (!before || !sameDocument(before, stored)) {
431	            nextLedger.record(op.id, 'restore', stored);
432	            changed = true;
433	          }
434	        }
435	      }
436	
437	      // Title conflicts are checked against the final projected set, so
438	      // operation order cannot make a swap or release-then-reuse fail.
439	      const titles = new Set();
440	      for (const document of candidate.list()) {
441	        if (titles.has(document.title)) {
442	          throw new HttpError(409, 'CONFLICT', `title conflict in batch: ${document.title}`);
443	        }
444	        titles.add(document.title);
445	      }
446	
447	      return changed;
448	    }, { dryRun });
449	    return { snapshot, changed: result === true };
450	  }
451	
452	  async function createDocument(req, res) {
453	    const bytes = await readBody(req);
454	    requireIfMatch(req);
455	    const document = validateDocument(parseJson(decodeJsonBody(bytes)));
456	    const { snapshot } = commit((candidate, nextLedger) => {
457	      if (candidate.get(document.id)) {
458	        throw new HttpError(409, 'CONFLICT', `document already exists: ${document.id}`);
459	      }
460	      assertTitleFree(candidate, document.title);
461	      candidate.add(document);
462	      if (nextLedger) nextLedger.record(document.id, 'create', candidate.get(document.id));
463	      return true;
464	    });
465	    sendJson(res, 201, snapshot, `"${snapshot.checksum}"`);
466	  }
467	
468	  async function replaceDocument(req, res, id) {
469	    const bytes = await readBody(req);
470	    requireIfMatch(req);
471	    const document = validateDocument(parseJson(decodeJsonBody(bytes)));
472	    if (document.id !== id) {
473	      throw new HttpError(400, 'ID_MISMATCH', `path id ${id} does not match body id ${document.id}`);
474	    }
475	    if (!current.get(id)) {
476	      throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
477	    }
478	    const before = current.get(id);
479	    const { snapshot } = commit((candidate, nextLedger) => {
480	      candidate.remove(id);
481	      assertTitleFree(candidate, document.title);
482	      candidate.add(document);
483	      const stored = candidate.get(id);
484	      // A replace whose normalized content is identical succeeds without
485	      // consuming a revision or touching the files.
486	      if (sameDocument(before, stored)) return false;
487	      if (nextLedger) nextLedger.record(id, 'replace', stored);
488	      return true;
489	    });
490	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
491	  }
492	
493	  function deleteDocument(req, res, id) {
494	    requireIfMatch(req);
495	    if (!current.get(id)) {
496	      throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
497	    }
498	    const { snapshot } = commit((candidate, nextLedger) => {
499	      candidate.remove(id);
500	      if (nextLedger) nextLedger.record(id, 'delete', null);
501	      return true;
502	    });
503	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
504	  }
505	
506	  function historyDocument(req, res, id) {
507	    if (!ledger) throw new HttpError(404, 'NOT_FOUND', `no route for GET /documents/${id}/history`);
508	    const entries = ledger.entries(id);
509	    if (!entries) throw new HttpError(404, 'NOT_FOUND', `document never existed: ${id}`);
510	    sendJson(res, 200, entries, currentEtag());
511	  }
512	
513	  async function restoreDocument(req, res, id) {
514	    if (!ledger) throw new HttpError(404, 'NOT_FOUND', `no route for POST /documents/${id}/restore`);
515	    const bytes = await readBody(req);
516	    requireIfMatch(req);
517	    // Bad UTF-8 is an INVALID_JSON transport-level failure; only once the
518	    // bytes decode do the restore-specific parse/shape rules apply, which
519	    // keep reporting INVALID_REVISION as before.
520	    const text = decodeJsonBody(bytes);
521	    let data;
522	    try {
523	      data = JSON.parse(text);
524	    } catch {
525	      throw new HttpError(400, 'INVALID_REVISION', 'request body must be an object containing only a positive integer revision');
526	    }
527	    if (!data || typeof data !== 'object' || Array.isArray(data)
528	      || Object.keys(data).length !== 1 || !Object.hasOwn(data, 'revision')
529	      || !Number.isInteger(data.revision) || data.revision < 1) {
530	      throw new HttpError(400, 'INVALID_REVISION', 'request body must be an object containing only a positive integer revision');
531	    }
532	    const chain = ledger.entries(id);
533	    if (!chain) throw new HttpError(404, 'NOT_FOUND', `document never existed: ${id}`);
534	    const target = ledger.entry(id, data.revision);
535	    if (!target) throw new HttpError(404, 'NOT_FOUND', `unknown revision ${data.revision} for document ${id}`);
536	    if (target.action === 'delete') {
537	      throw new HttpError(400, 'INVALID_REVISION', `revision ${data.revision} of document ${id} is a delete and cannot be restored`);
538	    }
539	    const before = current.get(id);
540	    const { snapshot } = commit((candidate, nextLedger) => {
541	      candidate.remove(id);
542	      assertTitleFree(candidate, target.document.title);
543	      candidate.add(target.document);
544	      const stored = candidate.get(id);
545	      // Restoring the already-current content succeeds without a new record.
546	      if (before && sameDocument(before, stored)) return false;
547	      nextLedger.record(id, 'restore', stored);
548	      return true;
549	    });
550	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
551	  }
552	
553	  async function batch(req, res) {
554	    const bytes = await readBody(req);
555	    requireIfMatch(req);
556	    const data = parseJson(decodeJsonBody(bytes));
557	    const { operations, dryRun } = validateBatchRequest(data);
558	    const { snapshot } = commitBatch(operations, dryRun);
559	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
560	  }
561	
562	  function listTags(req, res) {
563	    sendJson(res, 200, tagStats(current), currentEtag());
564	  }
565	
566	  // Applies the tag rules to the pre-rewrite tag set of every document. Each
567	  // original tag is looked up once, so a rule result is never itself rewritten
568	  // (a→b then b→c moves the original `a` straight to `b`) and swaps resolve
569	  // because `to` names are carried independently of the source keys. Returns
570	  // `{ snapshot, changedIds }` without persisting when `dryRun` is true or the
571	  // rewrite leaves the tag set unchanged.
572	  function commitTagRewrite(rules, dryRun) {
573	    const mapping = new Map(rules.map((rule) => [rule.from, rule.to]));
574	
575	    // Every source must be used by at least one currently-live document.
576	    const used = new Set();
577	    for (const document of current.list()) {
578	      for (const tag of document.tags) used.add(tag);
579	    }
580	    for (const from of mapping.keys()) {
581	      if (!used.has(from)) throw new HttpError(404, 'TAG_NOT_FOUND', `tag not in use: ${from}`);
582	    }
583	
584	    const { snapshot, result } = commit((candidate, nextLedger) => {
585	      const changedIds = [];
586	      for (const document of current.list()) {
587	        if (!document.tags.some((tag) => mapping.has(tag))) continue;
588	        // A null target removes the tag; mapped results are emitted as-is
589	        // without a second lookup, so new names are never chained further.
590	        const nextTags = normalizeTags(
591	          document.tags.flatMap((tag) => {
592	            if (!mapping.has(tag)) return [tag];
593	            const target = mapping.get(tag);
594	            return target === null ? [] : [target];
595	          }),
596	        );
597	        if (sameTags(document.tags, nextTags)) continue;
598	        const updated = { id: document.id, title: document.title, body: document.body, tags: nextTags };
599	        candidate.remove(document.id);
600	        candidate.add(updated);
601	        if (nextLedger) nextLedger.record(document.id, 'replace', candidate.get(document.id));
602	        changedIds.push(document.id);
603	      }
604	      // Tag set unchanged: report the current snapshot and no file/version work.
605	      if (changedIds.length === 0) return false;
606	      changedIds.sort(compareCodePoints);
607	      return changedIds;
608	    }, { dryRun });
609	    return { snapshot, changedIds: result ?? [] };
610	  }
611	
612	  async function rewriteTags(req, res) {
613	    const bytes = await readBody(req);
614	    requireIfMatch(req);
615	    const { rules, dryRun } = validateTagRules(parseJson(decodeJsonBody(bytes)));
616	    const { snapshot, changedIds } = commitTagRewrite(rules, dryRun);
617	    sendJson(res, 200, { snapshot, changedIds }, `"${snapshot.checksum}"`);
618	  }
619	
620	  // Merges an offline-edited incoming snapshot back against its base, keeping
621	  // non-conflicting online edits. The merge is computed against the current
622	  // live state; field/add/delete/title conflicts reject the whole request.
623	  // Each actually-changed document appends one ledger record (create for new
624	  // or reappearing ids, replace for edits, delete for removals), continuing
625	  // that id's revision sequence. Returns `{ snapshot, changedIds }` without
626	  // persisting when `dryRun` is true or the merge leaves the content equal to
627	  // the current state.
628	  function commitReconcile(base, incoming, dryRun) {
629	    const currentSnapshot = current.exportJSON();
630	    const result = reconcileSnapshots(currentSnapshot, base, incoming);
631	    if (result.conflicts.length > 0) {
632	      throw new HttpError(409, 'RECONCILE_CONFLICT', 'reconcile conflicts detected', {
633	        conflicts: result.conflicts,
634	      });
635	    }
636	
637	    const { snapshot } = commit((candidate, nextLedger) => {
638	      if (result.snapshot.checksum === currentSnapshot.checksum) return false;
639	      for (const document of current.list()) candidate.remove(document.id);
640	      for (const document of result.snapshot.documents) candidate.add(document);
641	      if (nextLedger) {
642	        for (const id of result.changedIds) {
643	          const stored = candidate.get(id);
644	          if (stored) {
645	            // A previously-deleted id that reappears continues its chain with a
646	            // create; a changed live document gets a replace.
647	            const action = current.get(id) ? 'replace' : 'create';
648	            nextLedger.record(id, action, stored);
649	          } else {
650	            nextLedger.record(id, 'delete', null);
651	          }
652	        }
653	      }
654	      return true;
655	    }, { dryRun });
656	    return { snapshot, changedIds: result.changedIds };
657	  }
658	
659	  async function reconcile(req, res) {
660	    const bytes = await readBody(req);
661	    requireIfMatch(req);
662	    const { base, incoming, dryRun } = validateReconcileRequest(parseJson(decodeJsonBody(bytes)));
663	    try {
664	      const snapshot = commitReconcile(base, incoming, dryRun).snapshot;
665	      sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
666	    } catch (error) {
667	      // Both snapshots must pass the existing validation; surface those
668	      // failures as INVALID_SNAPSHOT rather than an internal error. Save
669	      // failures keep their 500/IO_ERROR semantics.
670	      if (error instanceof SnapshotError && error.code === 'INVALID_SNAPSHOT') {
671	        throw new HttpError(400, 'INVALID_SNAPSHOT', error.message);
672	      }
673	      throw error;
674	    }
675	  }
676	
677	  async function handle(req, res) {
678	    const url = new URL(req.url, 'http://127.0.0.1');
679	    const segments = url.pathname.split('/').filter(Boolean).map(decodeURIComponent);
680	    const [resource, id, relation] = segments;
681	
682	    if (resource === 'documents' && segments.length === 1) {
683	      if (req.method === 'GET') {
684	        sendJson(res, 200, current.list(), currentEtag());
685	        return;
686	      }
687	      if (req.method === 'POST') {
688	        await createDocument(req, res);
689	        return;
690	      }
691	    } else if (resource === 'documents' && segments.length === 2) {
692	      if (req.method === 'GET') {
693	        const document = current.get(id);
694	        if (!document) throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
695	        sendJson(res, 200, document, currentEtag());
696	        return;
697	      }
698	      if (req.method === 'PUT') {
699	        await replaceDocument(req, res, id);
700	        return;
701	      }
702	      if (req.method === 'DELETE') {
703	        deleteDocument(req, res, id);
704	        return;
705	      }
706	    } else if (resource === 'documents' && segments.length === 3 && relation === 'links' && req.method === 'GET') {
707	      const links = current.links(id);
708	      if (!links) throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
709	      sendJson(res, 200, links, currentEtag());
710	      return;
711	    } else if (resource === 'documents' && segments.length === 3 && relation === 'history' && req.method === 'GET') {
712	      historyDocument(req, res, id);
713	      return;
714	    } else if (resource === 'documents' && segments.length === 3 && relation === 'restore' && req.method === 'POST') {
