716	      return;
717	    } else if (resource === 'batch' && segments.length === 1 && req.method === 'POST') {
718	      await batch(req, res);
719	      return;
720	    } else if (resource === 'tags' && segments.length === 1 && req.method === 'GET') {
721	      listTags(req, res);
722	      return;
723	    } else if (resource === 'tags' && segments.length === 2 && id === 'rewrite' && req.method === 'POST') {
724	      await rewriteTags(req, res);
725	      return;
